"""The How to page's content. GENERATED by `python -I tools/howto/howto.py build` from docs/howto:
never edit this file; edit docs/howto/sections/<id>.md (and guide.json for titles and order), then build."""

TITLE = 'PlanPlate how-to guide'
SUBTITLE = "Run bookings, the room and your restaurant's website: a guide for managers and staff."

SECTIONS = [
    {'id': 'getting-started', 'title': 'Getting started', 'who': 'Everyone',
     'html': '<p>PlanPlate runs in the web browser on a computer, tablet or phone. There is nothing to install.</p>\n<h3>Sign in or create an account</h3>\n<ol class="steps"><li><span>Open PlanPlate and use the sign-in box on the home page.</span></li><li><span>New here? Choose <strong>Create account</strong>, enter your name, email and a password, and accept the terms.</span></li><li><span>Were you invited by your restaurant? Sign up with <strong>the same email address the invitation went to</strong>. The restaurant is already waiting in your list.</span></li></ol>\n<figure class="shot"><img src="_/theme/howto-start-landing.webp?v=21ac25e3" width="1264" height="805" alt="The home page, with the sign-in box" loading="lazy"><figcaption>The home page, with the sign-in box</figcaption></figure>\n<figure class="shot phone"><img src="_/theme/howto-start-signup.webp?v=d57a1bb1" width="488" height="831" alt="Creating an account" loading="lazy"><figcaption>Creating an account</figcaption></figure>\n<h3>Your restaurants</h3>\n<p>After signing in you land on <strong>Restaurants</strong>. Each card shows today\'s hours, bookings, guests and seats, plus a badge with your role (<strong>Owner</strong>, <strong>Manager</strong> or <strong>Staff</strong>). A yellow banner lists bookings waiting for approval, and the bell at the top shows the same count on every page.</p>\n<ul><li><strong>Open</strong> goes to the restaurant\'s Today page.</li><li><strong>Bookings</strong> goes straight to Reservations.</li><li><strong>New restaurant</strong> adds another restaurant to your account.</li></ul>\n<figure class="shot"><img src="_/theme/howto-start-dashboard.webp?v=08a1d273" width="1264" height="805" alt="The Restaurants page" loading="lazy"><figcaption>The Restaurants page</figcaption></figure>'},
    {'id': 'roles', 'title': 'Who can do what', 'who': 'Owners and managers',
     'html': '<p>Everyone signs in with their own email. What they see depends on their role at each restaurant.</p>\n<div class="table"><table><thead><tr><th></th><th>Owner</th><th>Manager</th><th>Staff (waiters, hosts)</th></tr></thead><tbody><tr><td>Today, Reservations, walk-ins, seating</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Approve or decline requests</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Guest book</td><td>Yes</td><td>Yes</td><td>Look up only</td></tr><tr><td>Hours, tables, events, menu, gallery, website, QR codes</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Settings (booking rules, approvals, emails)</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Invite people and change their role</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Delete the restaurant</td><td>Yes</td><td>No</td><td>No</td></tr></tbody></table></div>\n<p>A manager sees every tab:</p>\n<figure class="shot"><img src="_/theme/howto-roles-tabs-manager.webp?v=a046af67" width="1208" height="220" alt="The tabs a manager sees" loading="lazy"><figcaption>The tabs a manager sees</figcaption></figure>\n<p>A waiter (Staff) sees only the three tabs they need to run the room:</p>\n<figure class="shot"><img src="_/theme/howto-roles-tabs-staff.webp?v=7230f43a" width="1208" height="174" alt="The tabs a waiter sees" loading="lazy"><figcaption>The tabs a waiter sees</figcaption></figure>\n<aside class="tip">Nobody can change or remove their own access. That way no one locks themselves out by mistake.</aside>'},
    {'id': 'team', 'title': 'Give someone access by email', 'who': 'Owners and managers',
     'html': '<p>Owners and managers can give someone access with just their email address.</p>\n<ol class="steps"><li><span>Open the restaurant and go to <strong>Settings</strong>, then <strong>Team</strong> (the last item in the list on the left).</span></li><li><span>Type the person\'s email address.</span></li><li><span>Pick <strong>Staff</strong> for a waiter or host, or <strong>Manager</strong> for someone who should also change settings.</span></li><li><span>Press <strong>Invite</strong>.</span></li></ol>\n<figure class="shot"><img src="_/theme/howto-team-invite.webp?v=33346288" width="980" height="470" alt="Inviting a waiter in Settings, Team" loading="lazy"><figcaption>Inviting a waiter in Settings, Team</figcaption></figure>\n<p>PlanPlate emails them an invitation. When they sign in, or create an account, <strong>with that same email</strong>, the restaurant appears in their list. Until then they show as invited.</p>\n<h3>Change or remove access</h3>\n<p>Each person on the team has a role menu and a remove button. Change <strong>Staff</strong> to <strong>Manager</strong> (or back) and it applies the next time their page loads. Remove someone who has left and they lose access right away. The owner\'s row can\'t be changed, and neither can your own.</p>'},
    {'id': 'today', 'title': 'Today', 'who': 'Everyone',
     'html': '<p><strong>Today</strong> is the restaurant\'s front page: whether you are open right now, and what the day looks like.</p>\n<ul><li><strong>Open now / Closed</strong>, with today\'s hours. Managers can press <strong>Change today\'s hours</strong> or <strong>Close today</strong> for a one-off change, such as a burst pipe or a private party.</li><li><strong>Four numbers</strong>: bookings today, guests today, guests in the room now, and requests waiting for approval. Tap one to open Reservations.</li><li><strong>Who\'s coming</strong>: the next arrivals. Tap <strong>Seat</strong> when a party arrives and <strong>Finish</strong> when they leave.</li><li><strong>Photo of the day</strong>: press <strong>Post</strong> to share today\'s dish or the terrace in the sun. It shows at the top of your website for 3 days.</li><li><strong>Specials</strong>, <strong>Coming up</strong> (events) and <strong>The week ahead</strong> fill the rest of the page.</li></ul>\n<figure class="shot"><img src="_/theme/howto-today-page.webp?v=2ea3529d" width="1264" height="805" alt="The Today page" loading="lazy"><figcaption>The Today page</figcaption></figure>'},
    {'id': 'reservations', 'title': 'Reservations: the host stand', 'who': 'Everyone',
     'html': '<p><strong>Reservations</strong> is the page to keep open on the host-stand tablet. It checks for new bookings every minute and keeps the screen awake. With <strong>Chime on</strong> it plays a short sound when a booking or request arrives. Tap the page once first, because browsers only play sound after a tap.</p>\n<h3>Requests waiting for approval</h3>\n<p>Bookings that need a decision appear at the top: for example, the restaurant was nearly full at that time, or the party is large. Each card says why it is waiting and how full you would be if you accept.</p>\n<ul><li><strong>Approve</strong> confirms the booking and emails the guest.</li><li><strong>Decline</strong> turns it down and emails the guest.</li><li><strong>Details</strong> opens the full booking, and <strong>See the day</strong> shows that date.</li></ul>\n<figure class="shot"><img src="_/theme/howto-res-approvals.webp?v=789ef4bb" width="1216" height="515" alt="Requests waiting for approval" loading="lazy"><figcaption>Requests waiting for approval</figcaption></figure>\n<h3>Three views of the day</h3>\n<p>Use <strong>Previous day</strong>, <strong>Next day</strong> and <strong>Today</strong> to move between dates, then switch views:</p>\n<ul><li><strong>Timeline</strong>: one row per table across the day, with a red line for now. Click an empty spot on a table\'s row to book it at that time. Striped bookings are waiting for approval, and a star marks a regular.</li><li><strong>List</strong>: every booking of the day in time order. Each row has a one-tap next step: <strong>Approve</strong> a request, <strong>Seat</strong> a guest who has arrived, <strong>Finish</strong> a table that has left. Tap the row itself to open the booking.</li><li><strong>Upcoming</strong>: every booking still to come, from today onwards.</li></ul>\n<figure class="shot"><img src="_/theme/howto-res-timeline.webp?v=d79df594" width="1264" height="805" alt="Timeline view: each table across the day" loading="lazy"><figcaption>Timeline view: each table across the day</figcaption></figure>\n<figure class="shot"><img src="_/theme/howto-res-list.webp?v=e0af1bae" width="1264" height="805" alt="List view with one-tap Seat" loading="lazy"><figcaption>List view with one-tap Seat</figcaption></figure>\n<figure class="shot"><img src="_/theme/howto-res-upcoming.webp?v=51a783b3" width="1264" height="805" alt="Upcoming: every booking still to come" loading="lazy"><figcaption>Upcoming: every booking still to come</figcaption></figure>\n<aside class="tip"><strong>Day sheet</strong> prints the day\'s bookings for the kitchen or the pass.</aside>'},
    {'id': 'bookings', 'title': 'Add a booking or a walk-in', 'who': 'Everyone',
     'html': '<h3>A booking by phone or in person</h3>\n<ol class="steps"><li><span>On <strong>Reservations</strong>, press <strong>New booking</strong>.</span></li><li><span>Pick the date, the time and the number of guests. <strong>Stays for</strong> is how long the table is held.</span></li><li><span>Leave <strong>Table</strong> on <strong>Best free table</strong>, or pick one. The line under it shows the best fit and how full you\'ll be.</span></li><li><span>Add the guest\'s name, phone and email. <strong>Taken by</strong> records how the booking came in.</span></li><li><span><strong>Guest\'s requests</strong> is what the guest asked for. <strong>Staff note</strong> is for the team only: guests never see it.</span></li><li><span>Leave <strong>Email the guest a confirmation</strong> ticked to send one (when there\'s an email address), then save.</span></li></ol>\n<figure class="shot"><img src="_/theme/howto-book-editor.webp?v=77b59218" width="1264" height="805" alt="Adding a booking" loading="lazy"><figcaption>Adding a booking</figcaption></figure>\n<p>If the time is full, PlanPlate says so and offers <strong>Save anyway</strong> for when you know you can squeeze them in.</p>\n<h3>A walk-in</h3>\n<p>Press <strong>Walk-in</strong> and tap the number of people. They are seated now, at the best free table. To add a name or a note, press <strong>Add a name or a note</strong> instead.</p>\n<figure class="shot"><img src="_/theme/howto-book-walkin.webp?v=f9624809" width="1264" height="805" alt="One tap seats a walk-in" loading="lazy"><figcaption>One tap seats a walk-in</figcaption></figure>\n<h3>Change, cancel or mark a no-show</h3>\n<p>Tap any booking to open it. From there you can change the details or press <strong>Approve</strong>, <strong>Decline</strong>, <strong>Seat now</strong>, <strong>Finished</strong>, <strong>No-show</strong> or <strong>Cancel booking</strong>. <strong>Call</strong> and <strong>Email</strong> links reach the guest, and <strong>Guest link</strong> opens the page the guest sees. A booking cancelled by mistake can be brought back with <strong>Restore booking</strong>.</p>'},
    {'id': 'guests', 'title': 'The guest book', 'who': 'Everyone',
     'html': '<p><strong>Guests</strong> is your guest book. Everyone who has booked is in it automatically, with their visits, how many people they brought, no-shows and cancellations. Search by name, phone, email or tag, and sort with the menu on the right.</p>\n<figure class="shot"><img src="_/theme/howto-guests-list.webp?v=83b151a7" width="1264" height="805" alt="The guest book" loading="lazy"><figcaption>The guest book</figcaption></figure>\n<p>Tap a guest to open their card:</p>\n<ul><li><strong>Tags</strong> such as Regular, VIP, Allergy or Birthday. Tags show as badges on their bookings, so the whole team sees them.</li><li><strong>Team notes</strong>: "likes the corner table", "allergic to shellfish". The guest never sees these.</li><li><strong>Visits and bookings</strong>: every past and future booking.</li></ul>\n<figure class="shot"><img src="_/theme/howto-guests-card.webp?v=34eec82b" width="1264" height="805" alt="A guest&#x27;s card, with tags and notes" loading="lazy"><figcaption>A guest\'s card, with tags and notes</figcaption></figure>\n<aside class="tip">Staff can look guests up. Only owners and managers can change tags and notes.</aside>'},
    {'id': 'hours', 'title': 'Opening hours and special days', 'who': 'Managers',
     'html': '<p>Guests can only book when you are open, so get your hours right first.</p>\n<h3>Regular hours and periods</h3>\n<p>A <strong>period</strong> sets the hours for each weekday between two dates, or for the whole year. You can have more than one: when periods overlap, <strong>the shorter one wins</strong>. So a "Summer" period overrides "Regular hours" for those dates. Press <strong>Edit</strong> on a period to change it, or <strong>Add a period</strong> for a new one. Two openings in one day (lunch and dinner) are fine.</p>\n<p>The calendar on the right shows the hours that apply on each day, month by month.</p>\n<figure class="shot"><img src="_/theme/howto-hours-page.webp?v=d1fdb277" width="1264" height="805" alt="Opening hours and the calendar" loading="lazy"><figcaption>Opening hours and the calendar</figcaption></figure>\n<h3>Special days</h3>\n<p>Closed for a holiday, or open late for New Year\'s Eve? Press <strong>Add a special day</strong>, pick the date (and an end date for several days), give it a label, then choose <strong>Closed</strong> or <strong>Special hours</strong>. Special days override every period.</p>\n<figure class="shot"><img src="_/theme/howto-hours-special.webp?v=8cd4cdb3" width="1264" height="805" alt="Adding a special day" loading="lazy"><figcaption>Adding a special day</figcaption></figure>'},
    {'id': 'tables', 'title': 'Tables and the floor plan', 'who': 'Managers',
     'html': '<p><strong>Tables &amp; layout</strong> is a drawing of your room. PlanPlate uses it to give each booking the best free table.</p>\n<ul><li><strong>Drag</strong> tables to where they stand in the room.</li><li><strong>Click</strong> a table to change its name and seats, or untick <strong>Available for bookings</strong> to take it out of use.</li><li><strong>Add a table</strong> puts a new one on the plan.</li><li><strong>Join tables</strong> turns two or more tables into one bookable table for larger parties. Choose the hours and days the join applies, for example only Friday and Saturday evenings.</li></ul>\n<p>Use <strong>Layout on</strong> (the weekday) and <strong>At</strong> (the hour) to see the room as guests can book it at that moment.</p>\n<figure class="shot"><img src="_/theme/howto-tables-plan.webp?v=c98c9d12" width="1264" height="805" alt="The floor plan" loading="lazy"><figcaption>The floor plan</figcaption></figure>'},
    {'id': 'events', 'title': 'Events', 'who': 'Managers',
     'html': '<p>Use <strong>Events</strong> for private parties, wine dinners or live music.</p>\n<ol class="steps"><li><span>Press <strong>Plan an event</strong> and fill in the date, the times and a description.</span></li><li><span>Tick <strong>Show it on our website</strong> for a public event. For a private party, tick <strong>Close online booking during the event</strong>; staff can still add bookings by hand.</span></li><li><span>Press <strong>Set up the room</strong> to arrange tables just for that event: start from the everyday layout, move tables, and <strong>Make one table</strong> from several. <strong>Save the room</strong> when done, and <strong>Print</strong> gives you the plan for the team.</span></li></ol>\n<figure class="shot"><img src="_/theme/howto-events-page.webp?v=95f00b12" width="1264" height="805" alt="Events" loading="lazy"><figcaption>Events</figcaption></figure>'},
    {'id': 'menu', 'title': 'Menu and specials', 'who': 'Managers',
     'html': '<p><strong>Menu</strong> holds your dishes in sections (Entrées, Plats, Desserts...) with prices and dietary labels such as V (vegetarian) and GF (gluten-free). The guest menu that the table QR code opens, your website and the menu widget all update the moment you save.</p>\n<ul><li><strong>Add a section</strong>, then add dishes to it. Use the pencil to edit a dish and the arrows to change the order.</li><li>When a dish runs out, press <strong>Sold out</strong>. Press it again when it\'s back.</li><li><strong>See the guest menu</strong> shows the menu exactly as guests see it.</li><li>Have a PDF or a photo of your menu? Use <strong>Upload a PDF or photo</strong> further down the page.</li></ul>\n<figure class="shot"><img src="_/theme/howto-menu-page.webp?v=d117656b" width="1264" height="805" alt="The menu editor" loading="lazy"><figcaption>The menu editor</figcaption></figure>\n<aside class="tip">Dishes of the day go in <strong>Specials</strong> on the Today page. They appear on your website when you add them and disappear when they end.</aside>'},
    {'id': 'gallery', 'title': 'Gallery', 'who': 'Managers',
     'html': '<p><strong>Gallery</strong> holds your photos: your best dishes, the room, the terrace, the team.</p>\n<ul><li>Photos <strong>in the gallery</strong> show on your website in the order you set. Use the eye button to show or hide a photo.</li><li><strong>Other photos and videos</strong> are kept for specials, events and the website, but don\'t appear in the gallery.</li><li><strong>Gallery style</strong> sets the look and the heading. Changes show on your website at once.</li><li><strong>Put it on another website</strong> gives you a code to paste into another site (in WordPress: a "Custom HTML" block). It always shows your latest photos.</li></ul>\n<figure class="shot"><img src="_/theme/howto-gallery-page.webp?v=303eebf4" width="1264" height="805" alt="The gallery" loading="lazy"><figcaption>The gallery</figcaption></figure>'},
    {'id': 'website', 'title': "Your restaurant's website", 'who': 'Managers',
     'html': '<p>PlanPlate can build a full website for your restaurant from what it already knows: your name, address, hours, menu, photos, specials and events. They stay up to date by themselves.</p>\n<ol class="steps"><li><span>Open <strong>Website</strong> and press <strong>Start from my details</strong>. It takes about 10 minutes. To see a finished one first, press <strong>See an example first</strong>.</span></li><li><span>Work through the steps on the left: <strong>Web address &amp; colours</strong>, then the texts and pictures. The preview on the right shows the site on a <strong>Computer</strong> or a <strong>Phone</strong>.</span></li><li><span>Press <strong>Save</strong>, then <strong>Publish</strong> to put it live. <strong>Open</strong> shows the live site, <strong>Download</strong> gives you a copy of the files, and <strong>Unpublish</strong> takes it down.</span></li></ol>\n<figure class="shot"><img src="_/theme/howto-website-page.webp?v=a7e9baeb" width="1264" height="805" alt="Building the restaurant website" loading="lazy"><figcaption>Building the restaurant website</figcaption></figure>'},
    {'id': 'share', 'title': 'Share links and QR codes', 'who': 'Managers',
     'html': '<p><strong>Share &amp; QR</strong> has everything you need to send guests to PlanPlate.</p>\n<ul><li><strong>QR codes</strong> for booking a table, the menu and your website. Use <strong>Download PNG</strong> for table cards, the window, the door and flyers. The codes open your live pages, so you never need to reprint them when the menu or hours change. There is also a ready-to-print A4 sheet of four table cards.</li><li><strong>Share &amp; embed</strong> gives the links and codes to put the booking form on your own website, your social pages and your Google Business Profile.</li></ul>\n<figure class="shot"><img src="_/theme/howto-share-page.webp?v=1f60d368" width="1264" height="805" alt="QR codes and links" loading="lazy"><figcaption>QR codes and links</figcaption></figure>'},
    {'id': 'settings', 'title': 'Settings: booking rules, approvals, emails', 'who': 'Managers',
     'html': '<p><strong>Settings</strong> is one long page. Use the list on the left to jump to a part, and press <strong>Save changes</strong> in the bar at the bottom when you are done (<strong>Discard</strong> undoes your changes).</p>\n<figure class="shot"><img src="_/theme/howto-settings-page.webp?v=8f8c99d0" width="1264" height="805" alt="Settings" loading="lazy"><figcaption>Settings</figcaption></figure>\n<ul><li><strong>Details</strong>: the name, description, address and contact details guests see.</li><li><strong>Booking rules</strong>: <strong>Table time</strong> (how long a booking holds its table), <strong>Time slots</strong>, <strong>Last booking</strong> before closing, <strong>Minimum notice</strong>, the <strong>Booking window</strong> (how many days ahead) and the <strong>Largest party online</strong>. You can also pause online booking here; guests are then asked to call.</li><li><strong>Approvals</strong>: when a booking confirms itself and when it waits for you (below).</li><li><strong>Booking form</strong>: a note shown on the form, such as "We hold tables for 15 minutes", in each language.</li><li><strong>Emails</strong>: whether guests get emails, the address that receives approval alerts, and the wording of the confirmed, waiting and declined messages.</li><li><strong>Languages</strong>: which languages the booking form offers (English, Français, Latviešu).</li><li><strong>Team</strong>: who has access (see "Give someone access by email").</li></ul>\n<h3>Approvals</h3>\n<p>Bookings confirm straight away while there is room. Past these limits a manager decides:</p>\n<ul><li><strong>Auto-confirm until</strong>: once this share of seats is taken at a time, new bookings wait for approval. 100% confirms everything that fits, and 0% sends every booking to you.</li><li><strong>Large parties</strong>: parties bigger than this always wait.</li><li><strong>When the limit is reached</strong>: take requests for you to approve, or stop online booking for that time and invite guests to walk in.</li><li><strong>Read requests first</strong>: tick <strong>Wait for me</strong> to approve every booking where the guest wrote a request (an allergy, a high chair, a birthday).</li></ul>\n<figure class="shot"><img src="_/theme/howto-settings-approvals.webp?v=ec825dd3" width="980" height="578" alt="The Approvals settings" loading="lazy"><figcaption>The Approvals settings</figcaption></figure>'},
    {'id': 'staff-view', 'title': "The waiter's view (Staff)", 'who': 'Staff',
     'html': '<p>This part is for waiters and hosts. Your manager adds you by email (see "Give someone access by email"). You then sign in, or create an account, with that email.</p>\n<p>The restaurant appears on your <strong>Restaurants</strong> page with a <strong>Staff</strong> badge. Press <strong>Open</strong> (Today) or <strong>Bookings</strong> (Reservations).</p>\n<figure class="shot"><img src="_/theme/howto-staff-dashboard.webp?v=cfb09193" width="1264" height="805" alt="A waiter&#x27;s Restaurants page" loading="lazy"><figcaption>A waiter\'s Restaurants page</figcaption></figure>\n<p>You have three tabs:</p>\n<ul><li><strong>Today</strong>: who\'s coming next, with <strong>Seat</strong> and <strong>Finish</strong>.</li><li><strong>Reservations</strong>: approve or decline requests, take phone bookings and walk-ins, seat guests, finish tables, and mark no-shows.</li><li><strong>Guests</strong>: look up a guest\'s visits, tags and the team\'s notes before they arrive.</li></ul>\n<figure class="shot"><img src="_/theme/howto-staff-reservations.webp?v=ee5c91dc" width="1264" height="805" alt="Reservations as a waiter sees it" loading="lazy"><figcaption>Reservations as a waiter sees it</figcaption></figure>\n<h3>A typical service</h3>\n<ol class="steps"><li><span>Open <strong>Reservations</strong> on the host-stand tablet and leave it open. It updates by itself, keeps the screen awake, and chimes for new bookings.</span></li><li><span>When a party arrives, tap <strong>Seat</strong> on their row.</span></li><li><span>Walk-ins: <strong>Walk-in</strong>, then tap the number of people.</span></li><li><span>When a table leaves, tap <strong>Finish</strong>, so the table shows free again.</span></li><li><span>Someone didn\'t come? Open their booking and press <strong>No-show</strong>. The guest book remembers it.</span></li></ol>\n<p>Opening hours, tables, the menu and settings are for managers. Ask a manager if something there needs changing.</p>'},
    {'id': 'phone', 'title': 'On a phone or tablet', 'who': 'Staff',
     'html': '<p>Everything works on a phone or tablet too. The pages stack into one column, the tabs scroll sideways, and the buttons are big enough to tap during service. <strong>Restaurants</strong> and <strong>You</strong> (your profile) sit at the bottom of the screen.</p>\n<div class="figs"><figure class="shot phone"><img src="_/theme/howto-phone-reservations.webp?v=7706eebd" width="780" height="1688" alt="Reservations on a phone" loading="lazy"><figcaption>Reservations on a phone</figcaption></figure><figure class="shot phone"><img src="_/theme/howto-phone-walkin.webp?v=7945a032" width="780" height="1688" alt="A walk-in on a phone" loading="lazy"><figcaption>A walk-in on a phone</figcaption></figure></div>\n<aside class="tip">On a tablet at the host stand, add PlanPlate to the home screen (in the browser\'s share or menu button, <strong>Add to Home Screen</strong>) so it is one tap away.</aside>'},
    {'id': 'guest-side', 'title': 'What your guests see', 'who': 'Everyone',
     'html': '<p>It helps to know what your guests see, so you can answer their questions.</p>\n<h3>The booking form</h3>\n<p>Guests reach it from your website, the <strong>Book a table</strong> QR code or the link on the Share page. They pick the number of guests, a day and a free time, then enter their name, email and phone. The form offers only times when you are open and have a table free. They can switch language at the top.</p>\n<figure class="shot"><img src="_/theme/howto-guest-book.webp?v=b437b564" width="1264" height="805" alt="The booking form: guests, day and free times" loading="lazy"><figcaption>The booking form: guests, day and free times</figcaption></figure>\n<p>After booking, the guest gets an email and a private link to their booking. There they can <strong>change</strong> or <strong>cancel</strong> it, and switch off PlanPlate news. If their booking needs your approval, they see that it is waiting, and they get an email when you approve or decline it.</p>\n<h3>The guest menu</h3>\n<p>The <strong>The menu</strong> QR code opens your live menu, with prices, dietary labels and today\'s specials. Sold-out dishes disappear as soon as you mark them.</p>\n<figure class="shot"><img src="_/theme/howto-guest-menu.webp?v=bc01c35d" width="1264" height="805" alt="The menu guests see" loading="lazy"><figcaption>The menu guests see</figcaption></figure>'},
    {'id': 'profile', 'title': 'Your profile', 'who': 'Everyone',
     'html': '<p>Tap the circle with your initials (top right, or <strong>You</strong> on a phone) to open your profile.</p>\n<ul><li><strong>Your name</strong>: shown to the rest of the team.</li><li><strong>Appearance</strong>: follow your device, or always <strong>Light</strong> or <strong>Dark</strong> (dark is easier on the eyes in a dim dining room).</li><li><strong>Password</strong>: <strong>Email me a reset link</strong> to choose a new one.</li><li><strong>Submit feedback</strong>: tell us about a problem or an idea.</li><li><strong>Sign out</strong>: always sign out on a shared device.</li></ul>\n<figure class="shot"><img src="_/theme/howto-profile-page.webp?v=5a51e204" width="1264" height="805" alt="Your profile" loading="lazy"><figcaption>Your profile</figcaption></figure>\n<aside class="tip">The person who pays for PlanPlate also sees the plan here, with <strong>Manage billing</strong> for invoices and the card on file.</aside>'},
]
